class Solution {
public:
    int mirrorFrequency(string s) {
        int f[128] = {};
        for (char c : s) ++f[(int)c];
        int ans = 0;
        for (int i = 0; i < 13; ++i)
            ans += abs(f['a'+i] - f['z'-i]);
        for (int i = 0; i < 5; ++i)
            ans += abs(f['0'+i] - f['9'-i]);
        return ans;
    }
};
